Script.script:
ObjectRegistryTemplate.alias_templates = {
  {
    "Objekt hinzufuegen",
    "^#{self:shortname()}add ([^|]+)\\|([^|]*)\\|([^|]*)\\|([^|]*)\\|([0-9]?)$",
    [[
---@pattern #{self:shortname()}add <Name>|<Ort>|<Region>|<Magier>|<Para>
---@desc Fuegt einen neuen {self.config.name}-Eintrag hinzu.
---@desc Para: 0 = Normalwelt (Standard), sonst Parallelweltnummer.
{self:name()}:add(matches[2], matches[3], matches[4], matches[5], tonumber(matches[6]) or 0)
  ]]
  },
  {
    "Namentlich hinzufuegen",
    "^#{self:shortname()}sadd (.+)$", 
    [[
---@pattern #{self:shortname()}sadd <Name>
---@desc Fuegt den Eintrag schnell hinzu; Ort und Region kommen aus GMCP.
{self:name()}:add(
  matches[2],
  gmcp.MG.room.info.short,
  gmcp.MG.room.info.domain,
  nil,
  PLAYER.world()
)
  ]]
  },
  {
    "Objekt loeschen",
    "^#{self:shortname()}del (\\d+)$", 
    [[
---@pattern #{self:shortname()}del <ID>
---@desc Loescht den Eintrag mit der angegebenen ID (Sicherheitsabfrage).
{self:name()}:delete(tonumber(matches[2]))
  ]]
  },
  {
    "Objekt suchen",
    "^#{self:shortname()}find (\\w+)$",
    [[
---@pattern #{self:shortname()}find <Name>
---@desc Zeigt alle Eintraege, deren Name die Eingabe enthaelt.
{self:name()}:find(matches[2])
  ]]
  },
  {
    "Komplexe Objektsuche",
    "^#{self:shortname()}finde (\\w+:\\w+(\\&\\w+:\\w+)*)$", 
    [[
---@pattern #{self:shortname()}finde <Feld>:<Wert>(&<Feld>:<Wert>)*
---@desc Komplexe Suche ueber mehrere Felder (alle Kriterien muessen zutreffen).
{self:name()}:find_complex(matches[2])
  ]]
  },
  {
    "Auflistung Objekte nach Attribut",
    "^#{self:shortname()}list (\\w+):(.*)$",
    [[
---@pattern #{self:shortname()}list <Feld>:<Wert?>
---@desc Listet alle vorhandenen Werte fuer das Feld auf (optional gefiltert).
{self:name()}:find_attr(matches[2], matches[3])
  ]]
  },
  {
    "Zeige Objekt",
    "^#{self:shortname()} (\\d+)$",
    [[
---@pattern #{self:shortname()} <ID>
---@desc Zeigt alle Details zum Eintrag mit dieser ID.
{self:name()}:show(tonumber(matches[2]))
  ]]
  },
  {
    "Notiz hinzufuegen",
    "^#{self:shortname()}note (\\d+) (\\d+)(\\s(.*))?$",
    [[
---@pattern #{self:shortname()}note <ID> <Pos> <Text>
---@desc Fuegt einen Hinweis hinzu, ersetzt oder loescht ihn (leerer Text = loeschen).
{self:name()}:edit_remark(tonumber(matches[2]), tonumber(matches[3]), matches[5])
  ]]
  },
  {
    "Attribut aendern",
    "^#{self:shortname()}change (\\d+) (\\w+):(.*)$",
    [[
---@pattern #{self:shortname()}change <ID> <Feld>:<Wert>
---@desc Aendert ein einzelnes Feld des Eintrags (Sicherheitsabfrage).
{self:name()}:change(tonumber(matches[2]), matches[3], matches[4])
  ]]
  }
}
